contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    // single public test function with one parameter to vary the call context
    function run(address /*unused*/ caller) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        // record balances before the call
        uint beforeTestBal = address(this).balance;
        uint beforeCbal = address(c).balance;

        bool reverted;
        c.sudicideAnyone(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Either the call reverted leaving balances as before, or it succeeded making C's balance zero
        // and this contract's balance at least as large as before (it may receive forwarded ETH).
        assert(reverted
               || (address(c).balance == 0 && address(this).balance >= beforeTestBal && beforeCbal == beforeCbal));
    }
    receive() external payable {}
}

